Definition tokit_cells_gen (r : tokres) (cur fst last : Z) : list cell :=
  match r with
  | TK_tok k l => TokItCells (cur + Z.of_nat k) (Z.of_nat l) (cur + Z.of_nat k + Z.of_nat l) fst last
  | _ => TokItCells 0 0 last last last
  end.

Lemma tokit_cells_gen_after : forall r it0 last, tokit_cells_after r it0 last = tokit_cells_gen r it0 it0 last.
Proof. intros [| |k l] it0 last; reflexivity. Qed.

Lemma tokit_cells_gen_shift : forall r cur fst last,
  tokit_cells_gen (tk_shift r) cur fst last = tokit_cells_gen r (cur + 1) fst last.
Proof.
  intros [| |k l] cur fst last; cbn; try reflexivity. unfold TokItCells.
  replace (cur + Z.of_nat (S k)) with (cur + 1 + Z.of_nat k) by lia. reflexivity.
Qed.

(* [comment removed for export] *)
Definition tokit_post_c (cells : list cell) (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (A W : Z) (wbs : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz A) a1 a2 a3 a4 a5 a6 a7
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom rsegs)
    /\ munch [(A, A + SZ_TOKIT)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ rw_cells rsegs m' A cells
    /\ bytes_at rsegs m' W wbs.

(* [comment removed for export] *)
Definition tokit_ctx (m m1 : mem) (A W : Z) (wbs : list byte) (cur fst La : Z) : Prop :=
  rw_cells rsegs m1 A (TokItCells 0 0 cur fst La)
  /\ bytes_at rsegs m1 W wbs
  /\ munch [(A, A + SZ_TOKIT)]%Z m m1 /\ wmono rsegs m m1 /\ mem_inv rsegs m1.

Definition tokit_pure (A W : Z) (wbs : list byte) (fst La : Z) : Prop :=
  La = W + Z.of_nat (length wbs) /\ La < 2^64 /\ 0 <= fst < 2^64
  /\ (A + SZ_TOKIT <= W \/ W + Z.of_nat (length wbs) <= A).

Local Ltac open_tctx CTX PURE :=
  destruct CTX as (OBJ & WIN & MU & WM & MI);
  destruct PURE as (HLA & LA64 & FST & SEP);
  pose proof (bytes_at_bound _ _ _ _ WIN) as WB;
  pose proof (rw_cells_bound _ _ _ _ OBJ) as OB; cbn [cells_size csize Nat.add TokItCells length] in OB;
  unfold TokItCells, SZ_TOKIT in *.

