Local Ltac win_loadH WIN q :=
  lazymatch type of WIN with bytes_at _ ?mx ?it0 ?bs =>
    let b := fresh "b" in let N := fresh "N" in let RD := fresh "RD" in let BR := fresh "BR" in
    destruct (win_byte _ _ _ q WIN ltac:(lia)) as [b N];
    pose proof (zb_range b) as BR; unfold zb in BR;
    pose proof (u8ro_read rsegs _ it0 bs (q - it0) b (Z_to_bv 64 q) WIN N ltac:(lia) ltac:(symmetry; apply wa_of_Z_to_bv; lia)) as RD;
    step; clear RD; change (zxb b) with (Z_to_bv 64 (zb b)); fold (zb b) in BR
  end.

(* [comment removed for export] *)
Local Ltac tab_tcharH c :=
  let TB := fresh "TB" in let RD := fresh "RD" in
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mx _) =>
  lazymatch goal with MI : mem_inv _ mx |- _ =>
    pose proof (tok_tab_bytes mx MI) as TB;
    pose proof (u8ro_read rsegs mx TOK_TAB TABB_TCHAR c (Z_to_bv 8 (nth (Z.to_nat c) TAB_IS_TOKEN_CHAR 0)) (Z_to_bv 64 (TOK_TAB + c)) TB
                 (tab_byte TAB_IS_TOKEN_CHAR c len_TCHAR ltac:(lia)) ltac:(lia) ltac:(symmetry; apply wa_of_Z_to_bv; lia)) as RD;
    unfold TOK_TAB in RD;
    step; clear RD TB; rewrite (tchar_load c) by lia; unfold wz
  end end.

