Lemma tincr_tok : forall (k i j : nat) (itv : Z) a5x a7x t0x t1x ra sp gp tp t2 s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (A W Fi La : Z) (wbs : list byte),
  (length wbs - j = k)%nat -> (i < j)%nat -> (j <= length wbs)%nat ->
  tokit_ctx m m1 A W wbs itv Fi La -> tokit_pure A W wbs Fi La ->
  evt rsegs (tokit_post_c (TokItCells (W + Z.of_nat i) (Z.of_nat (j - i + tspan (skipn j (zbytes wbs))))
