Local Ltac tincr_inc IH i W nc :=
  let KL := fresh "KL" in
  step; st1;
  replace (W + Z.of_nat i + 1) with (W + Z.of_nat (S i)) in * by lia;
  rewrite tokit_cells_gen_shift; replace (W + Z.of_nat i + 1) with (W + Z.of_nat (S i)) by lia;
  step; if_cases KL; zify_cond KL;
  [ eapply (IH true (S i) nc); [cbn; lia | lia | intros; lia | intros; discriminate | | assumption]
  | try (lazymatch goal with |- evt _ _ (MS _ _ (Z_to_bv 64 0x344cc) _ _ _ _) => step end);
    eapply (IH false (S i) nc);
    [cbn; lia | lia | intros; discriminate
    | let b' := fresh "b'" in let N' := fresh "N'" in
      intros _ b' N'; exfalso; pose proof (nth_error_lt _ _ _ N'); lia
    | | assumption] ];
  (split; [assumption | split; [assumption | split; [assumption | split; assumption]]]).

Lemma tincr_scan : forall (mu : nat) (ph : bool) (i : nat) (nc : bool) t0x t1x ra sp gp tp t2 s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (A W Fi La : Z) (wbs : list byte),
  (2 * (length wbs - i) + (if ph then 1 else 0) < mu)%nat ->
  (i <= length wbs)%nat -> (ph = true -> (i < length wbs)%nat) ->
  (ph = false -> forall b, nth_error wbs i = Some b -> is_ws (zb b) = false) ->
  tokit_ctx m m1 A W wbs (W + Z.of_nat i) Fi La -> tokit_pure A W wbs Fi La ->
  evt rsegs (tokit_post_c (tokit_cells_gen (tok_next nc (skipn i (zbytes wbs))) (W + Z.of_nat i) Fi La)
               ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc A W wbs m)
    (MS (mkR ra sp gp tp t0x t1x t2 s0 s1 (wz A) (wz (W + Z.of_nat i)) (wz La) (wz TOK_TAB) (wz 44) (wz 32) (wz 9)
              (wz (if nc then 1 else 0))
              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 (if ph then 0x3448c else 0x344a4)) fc None m1 (seg_rom rsegs)).
