Lemma b2z_xor_nez : forall x y, 0 <= x -> 0 <= y -> Z.b2z (0 <? Z.lxor x y) = (if negb (x =? y) then 1 else 0).
Proof.
  intros x y Hx Hy. pose proof (proj2 (Z.lxor_nonneg x y) ltac:(lia)) as NN.
  destruct (Z.eqb_spec x y) as [<-|NE].
  - rewrite Z.lxor_nilpotent. reflexivity.
  - cbn [negb]. assert (NZ : Z.lxor x y <> 0) by (intros E; apply NE; apply Z.lxor_eq_0_iff; exact E).
    replace (0 <? Z.lxor x y) with true by (symmetry; apply Z.ltb_lt; lia). reflexivity.
Qed.

Lemma tokit_incr_post_c : forall ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc A it fst La W wbs m,
  tokit_incr_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc A it fst La W wbs m
  = tokit_post_c (tokit_cells_after (tok_next (negb (it =? fst)) (tok_suffix W it wbs)) it La) ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc A W wbs m.
Proof. intros. reflexivity. Qed.

