Lemma optit_cells_after_shift : forall r lst cur err pad7,
  optit_cells_after (tk_shift r) lst cur err pad7 = optit_cells_after r lst (cur + 1) err pad7.
Proof.
  intros [| |k l] lst cur err pad7; cbn; try reflexivity. unfold OptItCells.
  replace (cur + Z.of_nat (S k)) with (cur + 1 + Z.of_nat k) by lia. reflexivity.
Qed.

Definition optit_post_c (cells : list cell) (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (A lst SP : Z) (sbs : list byte) (lrest : list cell) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz A) a1 a2 a3 a4 a5 a6 a7
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom rsegs)
    /\ munch [(A, A + SZ_TOKIT)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ rw_cells rsegs m' A cells
    /\ rw_cells rsegs m' lst (C8 (wz SP) :: C8 (wz (Z.of_nat (length sbs))) :: lrest)
    /\ bytes_at rsegs m' SP sbs.

Lemma optit_incr_post_c : forall ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc A lst it err SP pad7 sbs lrest m,
  optit_incr_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc A lst it err SP pad7 sbs lrest m
  = optit_post_c (optit_cells_after (tok_next (negb (it =? SP)) (tok_suffix SP it sbs)) lst it err pad7)
      ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc A lst SP sbs lrest m.
Proof. intros. reflexivity. Qed.

Definition optit_ctx (m m1 : mem) (A lst SP : Z) (sbs : list byte) (lrest : list cell) (cur err : Z) (pad7 : list byte) : Prop :=
  rw_cells rsegs m1 A (OptItCells lst cur 0 0 err pad7)
  /\ rw_cells rsegs m1 lst (C8 (wz SP) :: C8 (wz (Z.of_nat (length sbs))) :: lrest)
  /\ bytes_at rsegs m1 SP sbs
  /\ munch [(A, A + SZ_TOKIT)]%Z m m1 /\ wmono rsegs m m1 /\ mem_inv rsegs m1.

Definition optit_pure (A lst SP : Z) (sbs : list byte) (lrest : list cell) : Prop :=
  SP + Z.of_nat (length sbs) < 2^64
  /\ (A + SZ_TOKIT <= SP \/ SP + Z.of_nat (length sbs) <= A)
  /\ (A + SZ_TOKIT <= lst \/ lst + Z.of_nat (cells_size (C8 (wz SP) :: C8 (wz (Z.of_nat (length sbs))) :: lrest)) <= A).

Local Ltac open_octx CTX PURE :=
  destruct CTX as (OBJ & LSV & WIN & MU & WM & MI);
  destruct PURE as (SP64 & SEP & SEPL);
  pose proof (bytes_at_bound _ _ _ _ WIN) as WB;
  pose proof (rw_cells_bound _ _ _ _ OBJ) as OB; cbn [cells_size csize Nat.add OptItCells length] in OB;
  pose proof (rw_cells_bound _ _ _ _ LSV) as LB; cbn [cells_size csize Nat.add length] in LB, SEPL;
  unfold OptItCells, SZ_TOKIT in *.

