(* [comment removed for export] *)
Lemma optit_enderr : forall (cur : Z) a1x a4x a7x t0x t1x ra sp gp tp t2 s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (A lst SP err : Z) (sbs : list byte) (lrest : list cell) (pad7 : list byte),
  optit_ctx m m1 A lst SP sbs lrest cur err pad7 -> optit_pure A lst SP sbs lrest ->
  evt rsegs (optit_post_c (OptItCells lst 0 0 0 1 pad7) ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc A lst SP sbs lrest m)
    (MS (mkR ra sp gp tp t0x t1x t2 s0 s1 (wz A) a1x (wz (SP + Z.of_nat (length sbs))) (wz TOK_TAB) a4x (wz 32) (wz 9) a7x
              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
