Local Ltac optit_inc IH i SP nc :=
  let KL := fresh "KL" in
  step; st1;
  replace (SP + Z.of_nat i + 1) with (SP + Z.of_nat (S i)) in * by lia;
  rewrite optit_cells_after_shift; replace (SP + Z.of_nat i + 1) with (SP + Z.of_nat (S i)) by lia;
  step; if_cases KL; zify_cond KL;
  [ eapply (IH true (S i) nc); [cbn; lia | lia | intros; lia | intros; discriminate | | assumption]
  | try (lazymatch goal with |- evt _ _ (MS _ _ (Z_to_bv 64 0x3c238) _ _ _ _) => step end);
    eapply (IH false (S i) nc);
    [cbn; lia | lia | intros; discriminate
    | let b' := fresh "b'" in let N' := fresh "N'" in
      intros _ b' N'; exfalso; pose proof (nth_error_lt _ _ _ N'); lia
    | | assumption] ];
  (split; [assumption | split; [assumption | split; [assumption | split; [assumption | split; assumption]]]]).

Lemma optit_scan : forall (mu : nat) (ph : bool) (i : nat) (nc : bool) t0x t1x ra sp gp tp t2 s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (A lst SP err : Z) (sbs : list byte) (lrest : list cell) (pad7 : list byte),
  (2 * (length sbs - i) + (if ph then 1 else 0) < mu)%nat ->
  (i <= length sbs)%nat -> (ph = true -> (i < length sbs)%nat) ->
  (ph = false -> forall b, nth_error sbs i = Some b -> is_ws (zb b) = false) ->
  optit_ctx m m1 A lst SP sbs lrest (SP + Z.of_nat i) err pad7 -> optit_pure A lst SP sbs lrest ->
  evt rsegs (optit_post_c (optit_cells_after (tok_next nc (skipn i (zbytes sbs))) lst (SP + Z.of_nat i) err pad7)
               ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc A lst SP sbs lrest m)
    (MS (mkR ra sp gp tp t0x t1x t2 s0 s1 (wz A) (wz (SP + Z.of_nat i)) (wz (SP + Z.of_nat (length sbs))) (wz TOK_TAB)
              (wz 44) (wz 32) (wz 9) (wz (if nc then 1 else 0))
              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 (if ph then 0x3c1f8 else 0x3c210)) fc None m1 (seg_rom rsegs)).
